import ReactPixel from 'react-facebook-pixel';

const pixelId = import.meta.env.VITE_FACEBOOK_PIXEL_ID;
const isProd = import.meta.env.VITE_ENVIRONMENT === 'prod';
let initialized = false;

type EventOptions = {
  eventID?: string;
};

type ViewContentParams = {
  contentIds: string[] | string;
  contentName?: string | null;
};

type CompleteRegistrationParams = {
  contentName?: string;
  status?: string;
};

const createEventId = () => crypto.randomUUID();

export const isMetaPixelEnabled = () => isProd && Boolean(pixelId);

export const initializeMetaPixel = () => {
  if (!isMetaPixelEnabled() || initialized || !pixelId) {
    return;
  }

  ReactPixel.init(pixelId);
  initialized = true;
};

const trackStandardEvent = (
  eventName: string,
  data?: Record<string, unknown>,
  options?: EventOptions
) => {
  if (!isMetaPixelEnabled()) {
    return;
  }

  initializeMetaPixel();
  ReactPixel.fbq('track', eventName, data ?? {}, options ?? {});
};

export const trackMetaPageView = (pagePath?: string) => {
  const eventId = createEventId();
  trackStandardEvent(
    'PageView',
    pagePath
      ? {
          page_path: pagePath
        }
      : undefined,
    { eventID: eventId }
  );

  return eventId;
};

export const trackMetaViewContent = ({
  contentIds,
  contentName
}: ViewContentParams) => {
  trackStandardEvent('ViewContent', {
    content_ids: contentIds,
    content_name: contentName ?? undefined,
    content_type: 'product'
  });
};

export const trackMetaLead = (contentName = 'email_sign_up') => {
  trackStandardEvent('Lead', {
    content_name: contentName
  });
};

export const trackMetaCompleteRegistration = ({
  contentName = 'docshunt_sign_up',
  status = 'completed'
}: CompleteRegistrationParams = {}) => {
  trackStandardEvent('CompleteRegistration', {
    content_name: contentName,
    status
  });
};

type PurchaseParams = {
  value: number;
  currency: string;
  contents: Array<{
    id: string;
    quantity: number;
    item_price: number;
  }>;
  contentType: 'subscription' | 'credit' | 'seasonpass';
};

export const trackMetaPurchase = ({
  value,
  currency,
  contents,
  contentType
}: PurchaseParams) => {
  const eventId = createEventId();

  trackStandardEvent(
    'Purchase',
    {
      value,
      currency,
      contents,
      content_type: contentType,
      num_items: contents.reduce((sum, item) => sum + Number(item.quantity || 0), 0)
    },
    { eventID: eventId }
  );

  return eventId;
};
